SELECT COUNT(DISTINCT "CommonGovernment_4"."ag_name") AS "ctd_ag_name_ok",   COUNT(DISTINCT "CommonGovernment_4"."bureau_name") AS "ctd_bureau_name_ok",   COUNT(DISTINCT "CommonGovernment_4"."co_name") AS "ctd_co_name_ok",   COUNT(DISTINCT "CommonGovernment_4"."funding_agency_name") AS "ctd_funding_agency_name_ok",   COUNT(DISTINCT "CommonGovernment_4"."naics_code") AS "ctd_naics_code_ok",   COUNT(DISTINCT "CommonGovernment_4"."prod_or_serv_code") AS "ctd_prod_or_serv_code_ok",   COUNT(DISTINCT "CommonGovernment_4"."refidvid_piid") AS "ctd_refidvid_piid_ok",   SUM(CAST("CommonGovernment_4"."Number_of_Records" AS BIGINT)) AS "sum_Number_of_Records_ok",   SUM("CommonGovernment_4"."obligatedamount") AS "sum_obligatedamount_ok" FROM "CommonGovernment_4" HAVING (COUNT(1) > 0);
